-- Errata reading for O32: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','vitals')), htn AS (SELECT DISTINCT patient FROM (SELECT patient, lower(coalesce(json_extract(payload,'$.description'),'')) d, coalesce(json_extract(payload,'$.icd10'),'') i FROM r WHERE stream='conditions') WHERE ((d LIKE '%hypertension%' AND d NOT LIKE '%pulmonary hypertension%') OR d LIKE 'htn%' OR d LIKE 'essential htn%' OR i='I10')), bp AS (SELECT patient, json_extract(payload,'$.event_date') d, CAST(json_extract(payload,'$.blood_pressure_systolic') AS REAL) s, CAST(json_extract(payload,'$.blood_pressure_diastolic') AS REAL) di FROM r WHERE stream='vitals' AND json_extract(payload,'$.blood_pressure_systolic') IS NOT NULL AND json_extract(payload,'$.event_date') BETWEEN '2029-01-01' AND '2029-08-15'), l AS (SELECT patient, max(d) d FROM bp GROUP BY 1), lv AS (SELECT bp.patient, min(s) s, min(di) di FROM bp JOIN l USING(patient,d) GROUP BY 1), den AS (SELECT htn.patient FROM htn JOIN patients p ON p.id=htn.patient WHERE coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) BETWEEN 18 AND 85) SELECT round(100.0*sum(coalesce(lv.s<140 AND lv.di<90,0))/count(*),1) AS value FROM den LEFT JOIN lv ON lv.patient=den.patient;
